import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:platik_flutter/domain.dart';
import 'package:platik_flutter/store.dart';
import 'package:platik_flutter/rates.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';

void expectFields(Map actual,Map expected,Iterable<String> keys){for(final key in keys){if(expected[key] is num){expect(actual[key],closeTo((expected[key] as num).toDouble(),1e-8),reason:key);}else{expect(actual[key],expected[key],reason:key);}}}
void main(){
  TestWidgetsFlutterBinding.ensureInitialized();
  setUpAll(()async{await Catalog.load();await initializeDateFormatting('es');TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(native,(call)async=>null);});
  test('The complete currency/country catalogs are reused from the web source',(){expect(Catalog.currencies.length,179);expect(Catalog.countries.length,250);expect(Catalog.digits('JPY'),0);expect(Catalog.digits('KWD'),3);});
  final fixture=jsonDecode(File('test/fixtures/finance.json').readAsStringSync()) as Map;
  var index=0;
  for(final item in fixture['cases'] as List){final id=index++;test('Original web financial fixture $id (${item['currency']})',(){final data=Map<String,dynamic>.from(item['input'] as Map);final tx=rows(data['transactions']);final currency=item['currency'] as String;final summary=PeriodSummary(tx,currency,'2000-01-01','2099-12-31').toJson();expectFields(summary,item['summary'] as Map,summary.keys);final balance=AvailableBalance(data,currency).toJson();expectFields(balance,item['balance'] as Map,balance.keys);final categories=categoryTotals(tx,currency);expect(categories.length,(item['categories'] as List).length);for(var i=0;i<categories.length;i++){expectFields(categories[i],item['categories'][i] as Map,categories[i].keys);}});}
  test('Legacy APK data is migrated without losing cents, goals or the original backup',(){final original={'movements':[{'title':'Venta','kind':0,'amount':12345},{'title':'Insumos','kind':1,'amount':1234}],'goals':[{'title':'Ahorro','amount':100000,'saved':1050}],'currency':'BOB','name':'Ana'};final store=PlatikStore(original);expect(store.transactions.first['monto'],123.45);expect(store.transactions[1]['tipo'],'costo');expect(store.goals.first['ahorroAcumulado'],10.5);expect(store.root['legacyBackup'],original);expect(store.mode,'beta');expect(store.balance.amount,111.11);});
  test('Demo and beta stay independent, including resets',()async{final store=PlatikStore({});await store.upsert('transactions',{'id':'a','tipo':'ingreso','monto':10,'moneda':'BOB','fecha':today(),'descripcion':'Mi venta','categoria':'Ventas'});await store.switchMode('demo');expect(store.transactions.length,32);await store.reset();await store.switchMode('beta');expect(store.transactions.single['id'],'a');});
  test('An unconverted expense prevents overstating available money',(){final data=Catalog.fresh(false);data['transactions']=[{'tipo':'ingreso','monto':100,'moneda':'BOB'},{'tipo':'gasto','monto':10,'moneda':'USD'}];final b=AvailableBalance(data,'BOB');expect(b.amount,isNull);expect(b.status,'incompleto');});
  test('Opening balance and signed adjustments are separate from business income',(){final data=Catalog.fresh(false);data['openingBalance']={'monto':100,'moneda':'BOB'};data['balanceAdjustments']=[{'monto':-20,'moneda':'BOB'}];data['transactions']=[{'tipo':'ingreso','monto':30,'moneda':'BOB','fecha':today()}];expect(AvailableBalance(data,'BOB').amount,110);expect(PeriodSummary(rows(data['transactions']),'BOB',today(),today()).income,30);});
  test('Distribution never exceeds available money after rounding',(){for(final c in ['BOB','JPY','KWD']){for(final amount in [0.01,0.02,1.0,100.01]){final result=distributionAmounts(Catalog.defaults('empresa'),amount,c);final sum=(result['porCategoria'] as Map).values.fold<double>(0,(a,b)=>a+number(b));expect(sum,lessThanOrEqualTo(rounded(amount,c)+1e-9));expect(sum,closeTo(rounded(amount,c),1e-8));}}});
  test('Rate freshness rejects future and older-than-four-day publications',(){final now=DateTime.utc(2026,11,20);for(final delta in [-1,0,1,2,4,5]){final q={'status':'valid','publishedAt':now.subtract(Duration(days:delta)).toIso8601String()};expect(RateService.freshness(q,now:now),delta<0||delta>4?'desactualizada':delta<=1?'vigente':'anterior_vigente');}expect(RateService.freshness({'status':'expired','publishedAt':now.toIso8601String()},now:now),'desactualizada');});
  test('Historical snapshots are never overwritten when refreshing another base',()async{final store=PlatikStore({});final historical={'id':'a','monto':10,'moneda':'USD','tipo':'ingreso','fecha':today(),'baseAmount':70,'baseCurrency':'EUR','exchangeRate':7,'exchangeRateSource':'historical'};await store.patch({'transactions':[historical]});var calls=0;final rates=RateService(store,client:MockClient((request)async{calls++;return http.Response('{}',404);}));final result=await rates.refreshPending();expect(result,(0,1));expect(store.transactions.single,historical);expect(calls,0);});
  test('A real provider-shaped response records source, date and decimal precision',()async{final store=PlatikStore({});final date=DateTime.now().toUtc().toIso8601String().split('T').first;final rates=RateService(store,client:MockClient((request)async=>http.Response(jsonEncode({'base':'USD','quote':'BOB','rate':6.96,'date':date,'providers':[{'key':'BCBO'}]}),200)));final result=await rates.conversion('USD','BOB',2.5);expect(result['baseAmount'],17.4);expect(result['exchangeRateSource'],'frankfurter');expect(result['exchangeRatePublishedAt'],'${date}T00:00:00Z');});
  test('An unavailable quote never creates a fake equivalence',()async{final store=PlatikStore({});final rates=RateService(store,client:MockClient((request)async=>http.Response('{}',404)));expect(await rates.conversion('USD','BOB',10),isEmpty);});
}
